code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            objects.append((color, cells))
    def canon(cells):
        points = [(r,c) for r,c in cells]
        forms = []
        for reflect in (1,-1):
            for k in range(4):
                q=[]
                for r,c in points:
                    x,y=r,c*reflect
                    for _ in range(k): x,y=y,-x
                    q.append((x,y))
                mr=min(x for x,y in q); mc=min(y for x,y in q)
                forms.append(tuple(sorted((x-mr,y-mc) for x,y in q)))
        return min(forms)
    refs = {}
    for color, cells in objects:
        if color != 1:
            refs.setdefault(canon(cells), color)
    out = [row[:] for row in grid]
    for color, cells in objects:
        if color == 1 and canon(cells) in refs:
            for r,c in cells: out[r][c] = refs[canon(cells)]
    return out
